bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 30
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch();
const api=createTelegramBotApi({token:readPrivateToken(process.env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:20000});
let mask=0;
try{
 const rows=(await pool.query(`SELECT r.delivery_key,r.status,r.topic_id,r.paid_message_id,r.free_message_ids,r.sale_mode,l.paid_video_file_id,l.title,l.price_stars,l.seller_user_id,
 EXTRACT(EPOCH FROM (NOW()-r.updated_at)) AS age_seconds
 FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id
 WHERE r.status='sent' ORDER BY r.updated_at ASC`)).rows;
 const paidKeys=new Set((await pool.query("SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL")).rows.map(r=>r.delivery_key));
 const paid=rows.filter(r=>paidKeys.has(r.delivery_key));
 if(paid.length!==1||!Number.isSafeInteger(Number(paid[0].paid_message_id)))throw Error('PAID_POST_AMBIGUOUS');
 const selected=paid[0];
 const duplicates=rows.filter(r=>r.delivery_key!==selected.delivery_key&&r.topic_id===selected.topic_id&&r.seller_user_id===selected.seller_user_id&&r.title===selected.title&&r.price_stars===selected.price_stars&&r.paid_video_file_id===selected.paid_video_file_id&&!paidKeys.has(r.delivery_key));
 if(duplicates.length<1||duplicates.length>15)throw Error('DUPLICATE_COUNT_UNSAFE');
 const invoicePaid=(await pool.query("SELECT COUNT(*)::int AS count FROM videobot_video_invoice_orders WHERE telegram_payment_charge_id IS NOT NULL")).rows[0].count;
 if(invoicePaid!==0)throw Error('INVOICE_PURCHASERS_PRESENT');
 const ids=[selected.paid_message_id,...selected.free_message_ids].map(Number);
 const removeIds=duplicates.flatMap(r=>[r.paid_message_id,...(r.free_message_ids??[])].map(Number));
 if(ids.length!==3||new Set(ids).size!==3||removeIds.length!==duplicates.length*3||new Set(removeIds).size!==removeIds.length||removeIds.some(id=>ids.includes(id)||!Number.isSafeInteger(id)||id<=0))throw Error('MESSAGE_COLLISION');
 if(duplicates.some(r=>Number(r.age_seconds)>46*3600))throw Error('OLD_MESSAGES_CANNOT_DELETE');
 mask|=1;
 const chatId=-1002373696859;
 if(process.env.VIDEOBOT_VIDEO_SALE_THREAD_ID!==String(selected.topic_id))throw Error('TOPIC_CONFIGURATION_CHANGED');
 const me=await api('getMe',{});
 if(me?.is_bot!==true||me?.username?.toLowerCase()!=='createvdobot')throw Error('BOT_IDENTITY_CHANGED');
 const chat=await api('getChat',{chat_id:chatId});
 if(chat?.id!==chatId||chat?.is_forum!==true)throw Error('GROUP_NOT_VERIFIED');
 const member=await api('getChatMember',{chat_id:chatId,user_id:me.id});
 if(!['administrator','creator'].includes(member?.status)||member?.status==='administrator'&&member.can_delete_messages!==true)throw Error('DELETE_RIGHTS_UNVERIFIED');
 mask|=2;
 if(selected.sale_mode==='paid_media')mask|=4;
 if(duplicates.length>=2)mask|=8;
 if(Number(selected.paid_message_id)===4718)mask|=16;
 mask|=32;
}finally{await net.close();await pool.end()}
process.exit(mask);
NODE
